// 从仓库根 DESIGN.md 生成 visualize 技能的 design-tokens.md 参考文件。
// 立项与产物契约见 apps/acode-cli/specs/gen-ui-visualize.md
// 「DESIGN.md → design-tokens 生成管线」：设计系统文档是单一来源，模型消费的
// 技能参考是编译产物，两处不手抄（@generated 头纪律，厂商同源机制的自撰实现）。
//
// 手动运行，不接 build/tsup/vite：
//   node scripts/generate-visualize-design-tokens.mjs           # 重新生成产物
//   node scripts/generate-visualize-design-tokens.mjs --check   # 只比对不写入；漂移退出码 1
// 一致性测试：apps/acode-cli/tests/generate-visualize-design-tokens.test.mjs。
//
// 编译策略：字号表/间距/圆角/尺寸/动效五节**逐字搬运**（DESIGN.md 本身已过
// 格式门禁，逐字节稳定）；Color Palette 长散文**压缩**为「小节 → token 名列表」
// ——片段沙箱内没有 --color-* 变量，产物价值是角色词汇与数值比例，不是可引用值。
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join, resolve } from "node:path";

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const cliRoot = join(scriptDirectory, "..");
const repoRoot = join(cliRoot, "..", "..");

export const DESIGN_MD_PATH = join(repoRoot, "DESIGN.md");
export const OUTPUT_PATH = join(
  cliRoot,
  "packages",
  "bundled-skills",
  "skills",
  "visualize",
  "references",
  "design-tokens.md",
);

export const GENERATED_HEADER =
  "<!-- @generated by apps/acode-cli/scripts/generate-visualize-design-tokens.mjs " +
  "from DESIGN.md (repo root). Do not edit by hand — edit DESIGN.md, then re-run: " +
  "node scripts/generate-visualize-design-tokens.mjs -->";

const FRAMING = `# ACode design tokens — condensed from DESIGN.md

The design vocabulary a mockup needs to look like ACode: the type scale,
spacing rhythm, radius ladder, control sizes, motion stance, and color role
names. Boundary: the fragment sandbox does **not** define these CSS variables
— take the numbers, ratios, and role names from this file, and paint with the
theme variables the host injects (SKILL.md contract §2). Source of truth:
\`DESIGN.md\` at the repository root; this file is generated (see header).`;

const COLOR_TOKEN_PATTERN = /`(--color-[a-z0-9-]+)`/g;

/** 取 heading（整行精确匹配）到下一个同级或更高级标题之间的正文，逐字保留。 */
function extractSection(lines, heading) {
  const start = lines.findIndex((line) => line.trimEnd() === heading);
  if (start === -1) {
    // DESIGN.md 重排标题必须让生成器炸出来，而不是静默产出缺节的参考文件。
    throw new Error(`heading not found in DESIGN.md: ${heading}`);
  }
  const level = /^#+/.exec(heading)[0].length;
  const body = [];
  for (let index = start + 1; index < lines.length; index += 1) {
    const match = /^(#+)\s/.exec(lines[index]);
    if (match && match[1].length <= level) break;
    body.push(lines[index]);
  }
  return body.join("\n").trim();
}

/** Color Palette 节：按 ### 小节分组收集 --color-* token 名（去重保序）。 */
function extractColorRoles(lines) {
  const section = extractSection(lines, "## Color Palette");
  const roles = [];
  let current = null;
  for (const line of section.split("\n")) {
    const sub = /^###\s+(.+)$/.exec(line);
    if (sub) {
      current = { name: sub[1].trim(), tokens: [] };
      roles.push(current);
      continue;
    }
    if (!current) continue;
    for (const match of line.matchAll(COLOR_TOKEN_PATTERN)) {
      if (!current.tokens.includes(match[1])) current.tokens.push(match[1]);
    }
  }
  if (roles.length === 0) {
    throw new Error("no color roles extracted from DESIGN.md ## Color Palette");
  }
  return roles
    .map((role) => `- **${role.name}**: ${role.tokens.map((token) => `\`${token}\``).join(", ")}`)
    .join("\n");
}

/** 纯函数：DESIGN.md 全文 → 产物全文。测试直接调用做变异断言。 */
export function renderDesignTokensReference(designMarkdown) {
  // 统一换行为 LF：Windows 工作区读入可能带 CRLF，产物字节必须与平台无关。
  const lines = designMarkdown.replace(/\r\n/g, "\n").split("\n");
  return [
    GENERATED_HEADER,
    "",
    FRAMING,
    "",
    "## UI type scale",
    "",
    extractSection(lines, "### UI font tokens"),
    "",
    "## Spacing rhythm",
    "",
    extractSection(lines, "## Spacing"),
    "",
    "## Radius ladder",
    "",
    "### Container hierarchy",
    "",
    extractSection(lines, "### Container hierarchy"),
    "",
    "### Basic controls",
    "",
    extractSection(lines, "### Basic controls"),
    "",
    "## Control sizes",
    "",
    extractSection(lines, "### Common size baselines"),
    "",
    "## Motion",
    "",
    extractSection(lines, "## Motion"),
    "",
    "## Color roles (token names — values live in the host theme)",
    "",
    extractColorRoles(lines),
    "",
    "---",
    "",
    "Usage prose, approved exceptions, and component specs: read `DESIGN.md`.",
    "",
  ].join("\n");
}

async function main() {
  const checkOnly = process.argv.includes("--check");
  const designMarkdown = await readFile(DESIGN_MD_PATH, "utf8");
  const rendered = renderDesignTokensReference(designMarkdown);
  if (!checkOnly) {
    await writeFile(OUTPUT_PATH, rendered, "utf8");
    console.log(`generated ${OUTPUT_PATH}`);
    return;
  }
  let committed;
  try {
    committed = await readFile(OUTPUT_PATH, "utf8");
  } catch {
    console.error(`--check: missing generated file ${OUTPUT_PATH}; run the generator`);
    process.exit(1);
  }
  if (committed !== rendered) {
    console.error(
      "--check: design-tokens.md drifted from DESIGN.md; re-run " +
        "node scripts/generate-visualize-design-tokens.mjs",
    );
    process.exit(1);
  }
  console.log("--check: design-tokens.md is up to date");
}

// 仅作为脚本直跑时执行 main；被测试 import 时只导出纯函数（无副作用）。
// argv[1] 与 import.meta.url 都归一成绝对路径再比，Windows 分隔符/相对路径两态都对。
const isDirectRun =
  typeof process.argv[1] === "string" &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isDirectRun) {
  await main();
}
